package com.sakib.portebo.util;
import android.content.Context;import android.graphics.drawable.Drawable;import android.util.LruCache;import android.widget.ImageView;import com.sakib.portebo.R;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;
public final class IconCache {private static final LruCache<String,Drawable> CACHE=new LruCache<>(160);private static final ExecutorService WORKER=Executors.newFixedThreadPool(2);private IconCache(){}public static void load(Context context,String pkg,ImageView view){view.setTag(pkg);Drawable d=CACHE.get(pkg);if(d!=null){view.setImageDrawable(d);return;}view.setImageResource(R.drawable.ic_logo_porte);Context app=context.getApplicationContext();WORKER.execute(()->{try{Drawable icon=app.getPackageManager().getApplicationIcon(pkg);CACHE.put(pkg,icon);view.post(()->{if(pkg.equals(view.getTag()))view.setImageDrawable(icon);});}catch(Exception ignored){}});}}
